package com.farminghelper;

import java.util.*;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;

/** Native Bank Tags custom predicate, not persisted tags or a custom bank renderer. */
final class ActiveRunBank
{
    static final String TAG="farming helper active run";
    private final Client client;
    private final PluginManager plugins;
    private TagManager tags;
    private BankSearch search;
    private final ItemManager items;
    private Set<Integer> ids=Collections.emptySet(), admitted=Collections.emptySet();
    private int[] lastLayout=new int[0];
    private boolean registered,opened,offered,birdPhase;
    ActiveRunBank(Client client,PluginManager plugins,ItemManager items)
    {this.client=client;this.plugins=plugins;this.items=items;}
    private BankTagsPlugin service()
    {
        for(var p:plugins.getPlugins())if(p instanceof BankTagsPlugin&&plugins.isPluginActive(p))
        {
            // TagManager is deliberately bound inside the native plugin injector.
            // Reuse that exact instance without requiring Bank Tags as a dependency.
            TagManager actual=p.getInjector().getInstance(TagManager.class);
            if(tags!=actual){if(registered&&tags!=null)tags.unregisterTag(TAG);registered=false;tags=actual;admitted=Collections.emptySet();search=p.getInjector().getInstance(BankSearch.class);}
            return (BankTagsPlugin)p;
        }
        return null;
    }
    boolean bankOpen()
    {
        var root=client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        return client.getGameState()==GameState.LOGGED_IN&&root!=null&&!root.isHidden();
    }
    static boolean includes(Set<Integer> ids,int id,ItemComposition definition)
    {return ids.contains(id)&&definition!=null&&definition.getPlaceholderTemplateId()==-1;}
    private void register()
    {
        if(!registered){tags.registerTag(TAG,id->includes(admitted,id,items.getItemComposition(id))&&ids.contains(id));registered=true;}
    }
    /** One live ownership snapshot for both curation and positional layout.
     * Seed Vault stock and native bank placeholders are not bank shelf items. */
    static Map<Integer,Integer> ownedStock(Client client,IntFunction<ItemComposition> definition)
    {return ownedStock(client,definition,id->id);}
    static Map<Integer,Integer> ownedStock(Client client,IntFunction<ItemComposition> definition,IntUnaryOperator canonicalizeWorn)
    {
        Map<Integer,Integer> result=new HashMap<>(),worn=new HashMap<>();
        PhysicalStock.collect(result,client.getItemContainer(InventoryID.BANK),definition);
        PhysicalStock.collect(result,client.getItemContainer(InventoryID.INVENTORY),definition);
        PhysicalStock.collect(worn,client.getItemContainer(InventoryID.EQUIPMENT),definition);
        // Only normalize worn IDs for this visual shelf; exact supply stock is unchanged.
        worn.forEach((id,n)->result.merge(canonicalizeWorn.applyAsInt(id),n,Integer::sum));
        return Map.copyOf(result);
    }
    Map<Integer,Integer> ownedStock(){return ownedStock(client,items::getItemComposition,items::canonicalize);}
    private String name(int id){ItemComposition d=items.getItemComposition(id);return d==null?"":d.getName();}
    private int slot(int id){var s=items.getItemStats(id);return s==null||s.getEquipment()==null?-1:s.getEquipment().getSlot();}
    static Set<Integer> admittedIds(int[] layout)
    {
        Set<Integer> result=new HashSet<>();for(int id:layout)if(id>=0)result.add(id);
        return Set.copyOf(result);
    }
    private void open(BankTagsPlugin api,int[] layout)
    {
        // Publish only items already in the supplied layout. Native Bank Tags saves
        // a layout if a filtered item is missing from it. New IDs therefore cannot
        // enter through our predicate before their corresponding layout is ready.
        lastLayout=layout.clone();admitted=admittedIds(layout);
        api.openTag(TAG,new Layout(TAG,layout),BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM);
    }
    void tick(Set<Integer> next,Set<Integer> owned,boolean enabled,boolean bird)
    {
        if(!bankOpen()){release();return;}
        BankTagsPlugin api=service();
        if(!enabled||next==null||api==null){close(api);return;}
        boolean changed=updateEligible(next,owned);register();
        if(!opened){opened=true;offered=false;lastLayout=new int[0];}
        boolean stageChanged=birdPhase!=bird;birdPhase=bird;
        if(stageChanged)lastLayout=new int[0];
        if(offered&&!TAG.equals(api.getActiveTag()))return; // Respect manual browsing.
        int[] layout=BankShelfLayout.reconcile(lastLayout,ids,owned,this::name,this::slot,CuratedBank::transportCategory);
        if(!offered&&!ids.isEmpty()){offered=true;open(api,layout);}
        else if(!offered&&TAG.equals(api.getActiveTag()))api.closeBankTag();
        else if(offered&&(stageChanged||!Arrays.equals(layout,lastLayout)))open(api,layout);
        else if(offered&&changed&&search!=null)search.layoutBank();
    }
    void show(Set<Integer> next,Set<Integer> owned,boolean bird)
    {
        BankTagsPlugin api=service();
        if(api==null||next==null||next.isEmpty()||!bankOpen())return;
        updateEligible(next,owned);
        if(!opened||birdPhase!=bird)lastLayout=new int[0];birdPhase=bird;
        register();opened=true;offered=true;
        open(api,BankShelfLayout.reconcile(lastLayout,ids,owned,this::name,this::slot,CuratedBank::transportCategory));
    }
    private boolean updateEligible(Set<Integer> next,Set<Integer> owned)
    {
        Set<Integer> filtered=new HashSet<>(owned);filtered.retainAll(next);
        boolean changed=!ids.equals(filtered);ids=Set.copyOf(filtered);return changed;
    }
    void close(){close(bankOpen()?service():null);}
    private void close(BankTagsService api)
    {
        // Native Bank Tags can restore its remembered tag on reopen even after
        // our in-memory registration was released. Close only our exact tag.
        try{if(api!=null&&TAG.equals(api.getActiveTag())&&bankOpen())api.closeBankTag();}
        finally{release();}
    }
    private void release()
    {
        if(registered&&tags!=null)tags.unregisterTag(TAG);
        // Never save or delete another plugin's configuration. Registration is
        // in-memory; no actual TagTab or permanent item tag is created.
        registered=false;opened=false;offered=false;ids=Collections.emptySet();admitted=Collections.emptySet();lastLayout=new int[0];
    }
}

package com.farminghelper;

import java.util.*;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import java.util.regex.*;
import net.runelite.client.game.ItemVariationMapping;

/** Positional native Bank Tags layout. No custom bank rendering or item movement.
 * Physical stock is separate from layout positions, including withdrawal placeholders. */
final class BankShelfLayout
{
    static final int WIDTH=8;
    static final int PERMANENT=20,CHARGED=21,CONSUMABLE=22,TOOLS=23,COMPOST=24,SEEDS=25;
    private static final Pattern CHARGE=Pattern.compile("\\s*\\(([0-9]+)\\)$");
    private static final String[] RUNES={"air","water","earth","fire","law","nature","astral","cosmic","mist","dust","mud","smoke","steam","lava","blood","soul","death","mind","body"};
    private static final String[] TOOL_ORDER={"spade","rake","seed dibber","gardening trowel","watering can","gricoller","magic secateurs","secateurs","herb sack","silklined herb sack","seed box","reagent pouch","plant cure","axe","basket","sack","hammer","chisel","clockwork","bird house","birdhouse","logs"};
    private static final String[] COMPOST_ORDER={"empty bucket","bucket","empty bottomless compost","bottomless compost","compost","supercompost","ultracompost","volcanic ash","compost potion","saltpetre","coins"};
    private BankShelfLayout(){}
    private static String name(IntFunction<String> names,int id){return Objects.toString(names.apply(id),"").toLowerCase(Locale.ROOT);}
    private static String family(String n){return CHARGE.matcher(n).replaceFirst("").replaceFirst(" \\(i\\)$","").trim();}
    private static int charge(String n){Matcher m=CHARGE.matcher(n);return m.find()?Integer.parseInt(m.group(1)):0;}
    private static String baseName(IntFunction<String> names,int id)
    {String n=name(names,id);if(n.contains("graceful")||n.contains("farmer's"))return n;return name(names,ItemVariationMapping.map(id));}
    private static boolean outfit(String n,String kind){return n.contains(kind);}
    private static boolean diary(String n){return n.startsWith("ardougne cloak")||n.startsWith("explorer's ring")||n.startsWith("rada's blessing")||n.startsWith("karamja gloves")||n.startsWith("desert amulet")||n.startsWith("morytania legs")||n.startsWith("fremennik sea boots")||n.startsWith("kandarin headgear")||n.startsWith("wilderness sword")||n.startsWith("western banner");}
    private static boolean cape(String n){return n.contains("cape")&&!n.contains("graceful")&&!n.contains("escape");}
    private static boolean dive(String n){return n.equals("fishbowl helmet")||n.equals("diving apparatus")||n.equals("medallion of the deep")||n.equals("flippers");}
    private static boolean spellGear(String n){return n.contains("rune pouch")||n.startsWith("tome of ")||(n.contains("staff")&&!n.equals("dramen staff")&&!n.equals("lunar staff"));}
    private static boolean consumableTeleport(String n){return n.contains("tablet")||n.endsWith(" basalt")||n.contains("teleport scroll")||n.endsWith(" teleport")||n.endsWith(" teleport scroll");}
    private static boolean jewellery(String n){return n.startsWith("amulet ")||n.startsWith("ring ")||n.startsWith("skills necklace")||n.startsWith("games necklace")||n.startsWith("combat bracelet")||n.startsWith("necklace of passage")||n.startsWith("slayer ring")||n.startsWith("digsite pendant")||n.startsWith("pendant of ates")||n.startsWith("xeric's talisman")||n.startsWith("teleport crystal")||n.startsWith("pharaoh's sceptre");}
    private static int slot(String n,int actual)
    {
        if(n.contains("hood")||n.contains("helmet")||n.contains("strawhat"))return 0;
        if(n.contains("cape")||n.equals("diving apparatus"))return 1;
        if(n.startsWith("amulet")||n.equals("medallion of the deep")||n.equals("strung rabbit foot"))return 2;
        if(n.startsWith("tome of"))return 5;
        if(n.contains("graceful top")||n.contains("farmer's jacket")||n.contains("farmer's shirt"))return 4;
        if(n.contains("graceful legs")||n.contains("trousers")||n.contains("breeches"))return 7;
        if(n.contains("gloves"))return 9;
        if(n.contains("boots")||n.equals("flippers"))return 10;
        return actual;
    }
    // Same 4-column equipment silhouette as the native equipped layouts.
    private static int mannequinPos(int slot)
    {switch(slot){case 0:return 1;case 1:return 8;case 2:return 9;case 13:return 10;case 3:return 16;case 4:return 17;case 5:return 18;case 7:return 25;case 9:return 32;case 10:return 33;case 12:return 34;default:return -1;}}
    private static int order(String n,String[] ordered)
    {for(int i=0;i<ordered.length;i++)if(n.equals(ordered[i])||n.startsWith(ordered[i]+" ")||n.startsWith(ordered[i]+"("))return i;return ordered.length;}
    private static void pad(List<Integer> out){while(out.size()%WIDTH!=0)out.add(-1);}
    private static void block(List<Integer> out,List<Integer> ids)
    {if(ids.isEmpty())return;pad(out);out.addAll(ids);pad(out);}
    private static List<Integer> take(Set<Integer> left,java.util.function.IntPredicate condition,Comparator<Integer> comparator)
    {List<Integer> result=new ArrayList<>();for(int id:left)if(condition.test(id))result.add(id);result.sort(comparator);left.removeAll(result);return result;}
    private static void familyRows(List<Integer> out,List<Integer> items,IntFunction<String> names)
    {
        Map<String,List<Integer>> families=new TreeMap<>();for(int id:items)families.computeIfAbsent(family(name(names,id)),k->new ArrayList<>()).add(id);
        List<Integer> singletons=new ArrayList<>();
        for(List<Integer> group:families.values())
        {
            group.sort(Comparator.comparingInt((Integer id)->charge(name(names,id))).reversed().thenComparingInt(Integer::intValue));
            if(group.size()==1&&charge(name(names,group.get(0)))==0)singletons.add(group.get(0));else block(out,group);
        }
        block(out,singletons);
    }
    static int[] build(Set<Integer> owned,IntFunction<String> names,IntUnaryOperator equipment,IntUnaryOperator transport)
    {
        Set<Integer> left=new HashSet<>(owned);
        Comparator<Integer> byName=Comparator.comparing((Integer id)->name(names,id)).thenComparingInt(Integer::intValue);
        List<Integer> out=new ArrayList<>();
        // Two mannequins per row block. Extra recolors form further silhouettes,
        // never repeated IDs, and no synthetic unowned equipment.
        List<Integer> graceful=take(left,id->outfit(baseName(names,id),"graceful"),byName);
        List<Integer> farmer=take(left,id->outfit(baseName(names,id),"farmer's"),byName);
        List<Integer> overflow=new ArrayList<>();
        while(!graceful.isEmpty()||!farmer.isEmpty())
        {
            int[] cells=new int[40];Arrays.fill(cells,-1);
            for(int side=0;side<2;side++)
            {
                List<Integer> group=side==0?graceful:farmer;
                for(Iterator<Integer> iter=group.iterator();iter.hasNext();)
                {
                    int id=iter.next();int pos=mannequinPos(slot(baseName(names,id),equipment.applyAsInt(id)));
                    if(pos<0){overflow.add(id);iter.remove();continue;}
                    pos+=side*4;if(cells[pos]<0){cells[pos]=id;iter.remove();}
                }
            }
            if(Arrays.stream(cells).anyMatch(id->id>=0)){for(int id:cells)out.add(id);}
        }
        block(out,overflow);
        if(!out.isEmpty()&&!left.isEmpty()){pad(out);for(int i=0;i<WIDTH;i++)out.add(-1);}
        block(out,take(left,id->cape(name(names,id)),byName));
        block(out,take(left,id->dive(name(names,id)),Comparator.comparingInt((Integer id)->slot(name(names,id),equipment.applyAsInt(id))).thenComparing(byName)));
        block(out,take(left,id->diary(name(names,id)),byName));
        // Permanent travel accessories, then one row per jewellery family.
        block(out,take(left,id->transport.applyAsInt(id)==PERMANENT&&!jewellery(name(names,id))&&!consumableTeleport(name(names,id)),byName));
        familyRows(out,take(left,id->transport.applyAsInt(id)>=0&&jewellery(name(names,id)),byName),names);
        block(out,take(left,id->transport.applyAsInt(id)>=0&&!consumableTeleport(name(names,id)),byName));
        block(out,take(left,id->name(names,id).equals("dramen staff")||name(names,id).equals("lunar staff"),byName));
        // 4-column rune matrix on the left, spell equipment in the right-hand block.
        List<Integer> runes=take(left,id->name(names,id).endsWith(" rune"),byName);
        List<Integer> spell=take(left,id->spellGear(name(names,id)),Comparator.comparingInt((Integer id)->name(names,id).contains("rune pouch")?0:name(names,id).startsWith("tome of")?2:1).thenComparing(byName));
        if(!runes.isEmpty()||!spell.isEmpty())
        {
            if(!out.isEmpty()){pad(out);for(int i=0;i<WIDTH;i++)out.add(-1);}
            pad(out);int highest=runes.stream().mapToInt(id->Arrays.asList(RUNES).indexOf(name(names,id).replaceFirst(" rune$",""))).max().orElse(-1);
            int rows=Math.max((highest+4)/4,(spell.size()+3)/4);
            int[] cells=new int[rows*WIDTH];Arrays.fill(cells,-1);
            List<Integer> spare=new ArrayList<>();
            for(int id:runes){int i=Arrays.asList(RUNES).indexOf(name(names,id).replaceFirst(" rune$",""));if(i<0||cells[i/4*WIDTH+i%4]>=0)spare.add(id);else cells[i/4*WIDTH+i%4]=id;}
            for(int i=0;i<spell.size();i++)cells[i/4*WIDTH+4+i%4]=spell.get(i);
            for(int id:cells)out.add(id);block(out,spare);
        }
        block(out,take(left,id->consumableTeleport(name(names,id))||name(names,id).equals("master scroll book"),byName));
        block(out,take(left,id->{String n=name(names,id);return order(n,TOOL_ORDER)<TOOL_ORDER.length||n.contains(" axe")||n.endsWith(" logs")||n.contains("watering can");},Comparator.comparingInt((Integer id)->order(name(names,id),TOOL_ORDER)).thenComparing(byName)));
        block(out,take(left,id->order(name(names,id),COMPOST_ORDER)<COMPOST_ORDER.length||name(names,id).contains("compost"),Comparator.comparingInt((Integer id)->order(name(names,id),COMPOST_ORDER)).thenComparing(byName)));
        // Pot/seedling preparation is a separate shelf, not a new crop allocation.
        block(out,take(left,id->CuratedBank.saplingPreparation(name(names,id)),Comparator.comparingInt((Integer id)->{String n=name(names,id);return n.equals("plant pot")||n.equals("empty plant pot")?0:n.equals("filled plant pot")?1:n.endsWith("(w)")?3:2;}).thenComparing(byName)));
        Map<String,List<Integer>> crops=new TreeMap<>();
        for(int id:take(left,id->{String n=name(names,id);return CropCatalog.findByItemId(id)!=null||n.endsWith(" seed")||n.endsWith(" seeds")||n.contains("sapling")||n.endsWith(" spore")||n.endsWith(" spores");},byName))
        {
            Crop crop=VaultRanking.resolve(id,names.apply(id));String kind=crop==null?"Other planting":crop.getPatchType().getDisplayName();
            crops.computeIfAbsent(kind,k->new ArrayList<>()).add(id);
        }
        // All remaining explicit supplies, including protection payments, get their own block.
        block(out,take(left,id->true,byName));
        for(List<Integer> group:crops.values())block(out,group);
        while(!out.isEmpty()&&out.get(out.size()-1)==-1)out.remove(out.size()-1);
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
    /** Keep withdrawal positions for this bank visit. New stock appends as a
     * structured block; newly ineligible owned stock is removed. Empty
     * layout cells never enter the stock/requirement calculations. */
    static int[] reconcile(int[] prior,Set<Integer> eligible,Set<Integer> owned,IntFunction<String> names,IntUnaryOperator equipment,IntUnaryOperator transport)
    {
        if(prior.length==0)return build(eligible,names,equipment,transport);
        List<Integer> out=new ArrayList<>();Set<Integer> fresh=new HashSet<>(eligible);
        Set<Integer> previous=new HashSet<>();for(int id:prior)if(id>=0)previous.add(id);
        for(int id:prior)
        {
            if(id>=0&&owned.contains(id)&&!eligible.contains(id))out.add(-1);
            else if(id>=0&&!owned.contains(id))
            {
                // A consumed charge can change an ID, but not the shelf position.
                // Only replace with a newly owned, eligible charged family member;
                // never conflate different seeds, tools, or simultaneous stacks.
                String oldName=name(names,id);
                int replacement=fresh.stream().filter(n->!previous.contains(n)&&charge(oldName)>0&&
                    charge(name(names,n))>0&&family(oldName).equals(family(name(names,n)))&&
                    ItemVariationMapping.map(id)==ItemVariationMapping.map(n)&&transport.applyAsInt(id)==CHARGED&&
                    transport.applyAsInt(n)==CHARGED).min(Integer::compareTo).orElse(id);
                out.add(replacement);fresh.remove(replacement);
            }
            else{out.add(id);fresh.remove(id);}
        }
        if(!fresh.isEmpty()){pad(out);for(int id:build(fresh,names,equipment,transport))out.add(id);}
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

package com.farminghelper;

import java.time.Instant;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;
import com.farminghelper.queststate.CropState;
import com.farminghelper.queststate.QuestFarmingStateReader.Observation;
import com.farminghelper.queststate.QuestFarmingStateReader.Source;

/** Read-only adapter for native RuneLite Time Tracking birdhouse snapshots.
 * Native varp states and config keys: runelite timetracking/hunter/BirdHouseTracker,
 * BirdHouseSpace and BirdHouseState (BSD-2-Clause; see LICENSE-BIRDHOUSE).
 * Local object IDs: hong-niu/runelite-birdhouse-overlay BirdhouseOverlayPlugin.
 * Site coordinates corroborated by public BirdhouseLocation data (Rune-Server thread 708731);
 * live scene object ID remains authoritative; Shortest Path may select an adjacent walkable tile.
 * No native config writes or game interactions. */
final class BirdhouseRun
{
    enum Site
    {
        MEADOW_SOUTH("Tar Swamp entrance",VarPlayerID.BIRDHOUSE_TRANSMIT_B,30566,3679,3815),
        MEADOW_NORTH("Mushroom Meadow (North)",VarPlayerID.BIRDHOUSE_TRANSMIT_A,30565,3677,3882),
        VALLEY_SOUTH("Verdant Valley (Southwest)",VarPlayerID.BIRDHOUSE_TRANSMIT_D,30568,3763,3755),
        VALLEY_NORTH("Verdant Valley (Northeast)",VarPlayerID.BIRDHOUSE_TRANSMIT_C,30567,3768,3761);
        final String label;final int varp,object;final WorldPoint approach;
        Site(String label,int varp,int object,int x,int y){this.label=label;this.varp=varp;this.object=object;this.approach=new WorldPoint(x,y,0);}
    }
    static List<FarmRunPatch> patches()
    {
        List<FarmRunPatch> result=new ArrayList<>();
        for(Site site:Site.values())result.add(new FarmRunPatch("Fossil Island",site.label,PatchType.BIRDHOUSE));
        return result;
    }
    static Site site(FarmRunPatch p)
    {for(Site s:Site.values())if(s.label.equals(p.getName()))return s;return null;}
    static int order(FarmRunPatch p){Site s=site(p);return s==null?Integer.MAX_VALUE:s.ordinal();}
    static boolean isObject(int id)
    {for(Site s:Site.values())if(s.object==id)return true;return false;}
    static boolean seeded(int raw){return raw>0&&raw<=27&&raw%3==0;}
    static CropState decode(int raw,long timestamp,long now)
    {
        if(raw<0||raw>27)return null;
        if(raw==0)return CropState.EMPTY;
        if(!seeded(raw))return CropState.FILLING;
        if(timestamp<=0||timestamp>now)return null;
        return now-timestamp>=3000?CropState.HARVESTABLE:CropState.GROWING;
    }
    static Observation observe(Client client,ConfigManager config,FarmRunPatch p,boolean local)
    {
        Site s=site(p);int cached=-1;long time=0;
        if(s==null)return new Observation(null,Source.NONE,0,null,p.getName());
        String value=config.getRSProfileConfiguration("timetracking","birdhouse."+s.varp);
        if(value!=null)try{String[] parts=value.split(":");if(parts.length==2){cached=Integer.parseInt(parts[0]);time=Long.parseLong(parts[1]);}}catch(NumberFormatException ignored){}
        int raw=local?client.getVarpValue(s.varp):cached;
        long now=Instant.now().getEpochSecond();
        if(raw!=cached)time=0;
        return new Observation(decode(raw,time,now),local?Source.LIVE:cached>=0?Source.TIME_TRACKING:Source.NONE,time*1000,null,p.getName(),raw);
    }
    private static final int[] HOUSES={ItemID.BIRDHOUSE_NORMAL,ItemID.BIRDHOUSE_OAK,ItemID.BIRDHOUSE_WILLOW,ItemID.BIRDHOUSE_TEAK,ItemID.BIRDHOUSE_MAPLE,ItemID.BIRDHOUSE_MAHOGANY,ItemID.BIRDHOUSE_YEW,ItemID.BIRDHOUSE_MAGIC,ItemID.BIRDHOUSE_REDWOOD};
    private static final int[] LOGS={1511,1521,1519,6333,1517,6332,1515,1513,19669};
    private static final int[] HUNTER={5,14,24,34,44,49,59,74,89};
    private static final int[] CRAFT={5,15,25,35,45,50,60,75,90};
    private static final int[] BAIT={ItemID.POTATO_SEED,ItemID.ONION_SEED,ItemID.CABBAGE_SEED,ItemID.BARLEY_SEED,ItemID.HAMMERSTONE_HOP_SEED,ItemID.ASGARNIAN_HOP_SEED,ItemID.JUTE_SEED,ItemID.YANILLIAN_HOP_SEED,ItemID.KRANDORIAN_HOP_SEED,ItemID.TOMATO_SEED,ItemID.SWEETCORN_SEED,ItemID.STRAWBERRY_SEED};
    static Map<FarmRunPatch,String> supplies(List<FarmRunPatch> ready,Map<FarmRunPatch,Observation> states,
        Map<Integer,Integer> stock,Map<Integer,Integer> required,int hunter,int crafting)
    {
        Map<Integer,Integer> left=new HashMap<>(stock);
        required.forEach((id,n)->left.merge(id,-n,Integer::sum));
        Map<FarmRunPatch,String> result=new LinkedHashMap<>();
        int bait=0,clockworks=0;
        for(FarmRunPatch p:ready)
        {
            if(p.getPatchType()!=PatchType.BIRDHOUSE)continue;
            Observation o=states.get(p);
            if(o.state==CropState.FILLING)
            {bait+=10;result.put(p,"Fill the existing birdhouse with suitable seeds.");continue;}
            String instruction=o.state==CropState.EMPTY?"Build and bait the empty birdhouse spot.":o.state==CropState.HARVESTABLE?"Empty the ready birdhouse, recover the clockwork, replace and bait it.":"Inspect the birdhouse; if ready, empty, replace and bait it. Do not dismantle a growing trap.";
            bait+=10;
            boolean found=false;
            for(int i=HOUSES.length-1;i>=0;i--)
            {
                if(hunter<HUNTER[i])continue;
                if(left.getOrDefault(HOUSES[i],0)>0)
                {required.merge(HOUSES[i],1,Integer::sum);left.merge(HOUSES[i],-1,Integer::sum);found=true;break;}
                if(crafting>=CRAFT[i]&&left.getOrDefault(LOGS[i],0)>0)
                {
                    required.merge(LOGS[i],1,Integer::sum);left.merge(LOGS[i],-1,Integer::sum);
                    required.put(2347,1);required.put(1755,1);
                    if(o.state!=CropState.HARVESTABLE)clockworks++;
                    found=true;break;
                }
            }
            if(!found)
            {
                int i=HOUSES.length-1;while(i>0&&(hunter<HUNTER[i]||crafting<CRAFT[i]))i--;
                if(crafting>=CRAFT[i]&&hunter>=HUNTER[i]){required.merge(LOGS[i],1,Integer::sum);required.put(2347,1);required.put(1755,1);if(o.state!=CropState.HARVESTABLE)clockworks++;}
                else{int h=HOUSES.length-1;while(h>0&&hunter<HUNTER[h])h--;required.merge(HOUSES[h],1,Integer::sum);}
            }
            result.put(p,instruction);
        }
        if(clockworks>0)required.merge(8792,clockworks,Integer::sum);
        for(int id:BAIT)
        {
            int n=Math.min(bait,Math.max(0,left.getOrDefault(id,0)));
            if(n>0){required.merge(id,n,Integer::sum);bait-=n;}
            if(bait==0)break;
        }
        if(bait>0)required.merge(ItemID.POTATO_SEED,bait,Integer::sum);
        return result;
    }
    static Set<Integer> stepItems(FarmRunPatch p,Observation o,Map<Integer,Integer> stock,Map<Integer,Integer> bag,Map<Integer,Integer> farming,int hunter,int crafting)
    {
        if(o.state!=CropState.EMPTY&&o.state!=CropState.FILLING)return Collections.emptySet();
        Map<Integer,Integer> needed=new HashMap<>(farming);
        supplies(List.of(p),Map.of(p,o),stock,needed,hunter,crafting);
        if(o.state==CropState.FILLING)
        {
            for(int id:BAIT)if(needed.getOrDefault(id,0)>farming.getOrDefault(id,0)&&bag.getOrDefault(id,0)>0)return Set.of(id);
            return Collections.emptySet();
        }
        for(int id:HOUSES)if(needed.getOrDefault(id,0)>farming.getOrDefault(id,0)&&bag.getOrDefault(id,0)>0)return Set.of(id);
        for(int id:LOGS)if(needed.getOrDefault(id,0)>farming.getOrDefault(id,0)&&bag.getOrDefault(id,0)>0&&bag.getOrDefault(8792,0)>0)return Set.of(id,8792);
        return Collections.emptySet();
    }
    private BirdhouseRun(){}
}

