import net.runelite.api.coords.WorldPoint;
import static com.farminghelper.RouteLeg.Interaction.*;

/** Transport legs from Shortest Path boats/transports.tsv and RuneLite MooringLocation.
 * Interior patch approach is derived from actual observed objects, not the world-map icon. */
final class SpecialRoutes
{
    static final WorldPoint HESPORI_ENTRANCE=new WorldPoint(1230,3730,0); // approximate; resolve cave object locally
    static final WorldPoint SEAWEED_ISLAND=new WorldPoint(3764,3899,0);
    static final WorldPoint CORAL_ENTRANCE=new WorldPoint(3271,2463,0);
    static final WorldPoint CORAL_EXIT_POINT=new WorldPoint(3288,8868,1);
    static final WorldPoint ANGLER_ROWBOAT=new WorldPoint(2543,2844,0);
    static final WorldPoint CORSAIR_MOORING=new WorldPoint(2579,2843,0);
    static final WorldPoint ANGLER_MOORING=new WorldPoint(2467,2721,0);
    static final int ANGLER_ROWBOAT_VARBIT=18355;
    static boolean insideHespori(WorldPoint p){return p!=null && p.getRegionID()==5021;}
    static boolean insideSeaweed(WorldPoint p){return p!=null && p.getRegionID()==15008;}
    static boolean insideCoral(WorldPoint p){return p!=null && p.getRegionID()==13194;}
    static boolean onAnglers(WorldPoint p){return p!=null && p.getRegionID()==9770;}
    static boolean anglers(FarmRunPatch p){return p!=null && "Anglers' Retreat".equals(p.getLocation());}
    static boolean isType(FarmRunPatch p,PatchType type){return p!=null && p.getPatchType()==type;}
    static RouteLeg leg(FarmRunPatch patch,WorldPoint player,boolean aboard,boolean rowboat,boolean instance,WorldPoint liveApproach)
    {
        if(insideHespori(player))
        {
            if(!isType(patch,PatchType.HESPORI))return RouteLeg.manual("Leave the Hespori cave through its exit.",HESPORI_EXIT);
            return RouteLeg.walk(null,false); // instance: local object guidance only
        }
        if(insideSeaweed(player))
        {
            if(!isType(patch,PatchType.SEAWEED))return RouteLeg.manual("Use the underwater exit to resurface at the bank island.",SURFACE);
            return RouteLeg.walk(instance?null:liveApproach,true);
        }
        if(insideCoral(player))
        {
            if(!isType(patch,PatchType.CORAL))return player.getPlane()==1 && !instance
                ? RouteLeg.approach(CORAL_EXIT_POINT,"Climb the steps to leave the Coral Nurseries.",CORAL_EXIT)
                : RouteLeg.manual("Return to the nursery exit steps and climb out.",CORAL_EXIT);
            return RouteLeg.walk(instance?null:liveApproach,true);
        }
        if(patch==null)return RouteLeg.walk(null,false);
        if(aboard)
        {
            if(anglers(patch))return new RouteLeg(ANGLER_MOORING,"Sail to Anglers' Retreat, moor and disembark.",MOOR,false);
            return RouteLeg.manual("Moor and disembark before continuing to the next farm.",MOOR);
        }
        boolean house=instance&&LocationContext.isHouse(player);
        if(instance&&!house)return RouteLeg.manual("Leave the current instance to resume travel.",NONE);
        if(isType(patch,PatchType.HESPORI))return RouteLeg.approach(HESPORI_ENTRANCE,"Enter the cave beside Arno in the west wing.",HESPORI_ENTER);
        if(isType(patch,PatchType.SEAWEED))return RouteLeg.approach(SEAWEED_ISLAND,"Travel to the bank island and choose Dive on the rowboat.",DIVE);
        if(isType(patch,PatchType.CORAL))return RouteLeg.approach(CORAL_ENTRANCE,"Climb down the steps at the eastern dock. Bring diving equipment or a Medallion of the deep.",CORAL_ENTER);
        if(anglers(patch) && !onAnglers(player))
        {
            if(!rowboat)return RouteLeg.approach(CORSAIR_MOORING,"Board your boat at Corsair Cove, sail to Anglers' Retreat and moor. Build the rowboat utility for future visits.",BOARD);
            return RouteLeg.approach(Waypoints.destination(patch),"Travel via the unlocked Anglers' Retreat rowboat.",NONE);
        }
        // If leaving the island without the permanent rowboat, do not ask a land pathfinder to cross sea.
        if(onAnglers(player) && !anglers(patch) && !rowboat)
            return RouteLeg.approach(ANGLER_MOORING,"Board your boat, sail to a mainland port and disembark.",BOARD);
        WorldPoint target=liveApproach==null?Waypoints.destination(patch):liveApproach;
        return RouteLeg.walk(target,house || QuestTargets.get(patch)==null || liveApproach!=null);
    }
}

package com.farminghelper;

import java.util.*;

/** Mixed farming runs finish on Fossil Island; birds have their own supply stage. */
final class SpecialtyStages
{
    static boolean includes(boolean staged,boolean birdPhase,PatchType type)
    {return !staged || (type==PatchType.BIRDHOUSE)==birdPhase;}
    static boolean fossil(FarmRunPatch patch){return "Fossil Island".equals(RunOrder.site(patch));}
    static boolean stageBirds(String policy,Set<FarmRunType> types)
    {return "group_SPECIALTY".equals(policy)||("manual".equals(policy)&&types.contains(FarmRunType.BIRDHOUSE)&&types.size()>1);}
    static boolean fossilLastRequired(String policy){return "manual".equals(policy)||"group_SPECIALTY".equals(policy);}
    static int fossilOrder(FarmRunPatch patch)
    {switch(patch.getPatchType()){case HARDWOOD_TREE:return 0;case SEAWEED:return 1;case BIRDHOUSE:return 2;default:return 0;}}
    static List<RunOrder.Group> fossilLast(List<RunOrder.Group> groups)
    {
        List<RunOrder.Group> ordered=new ArrayList<>(groups);
        ordered.sort(Comparator.comparingInt(g->"Fossil Island".equals(g.site)?1:0));
        for(int i=0;i<ordered.size();i++)
        {
            RunOrder.Group g=ordered.get(i);if(!"Fossil Island".equals(g.site))continue;
            List<FarmRunPatch> patches=new ArrayList<>(g.patches);
            patches.sort(Comparator.comparingInt(SpecialtyStages::fossilOrder).thenComparingInt(p->p.getPatchType()==PatchType.BIRDHOUSE?BirdhouseRun.order(p):0));
            if(!patches.equals(g.patches))ordered.set(i,new RunOrder.Group(g.site,patches));
        }
        return ordered;
    }
    static Map<Integer,Integer> birdStock(Map<Integer,Integer> bag,Map<Integer,Integer> bank)
    {
        Map<Integer,Integer> result=new HashMap<>(bag);
        bank.forEach((id,n)->result.merge(id,n,Integer::sum));
        return result;
    }
    private SpecialtyStages(){}
}

package com.farminghelper;

import javax.annotation.Nullable;
import com.farminghelper.queststate.CropState;

/**
 * The conditional-step semantics adapted from Quest Helper HerbRun/TreeRun:
 * evaluate the observed patch state before choosing an action. This model
 * deliberately does not issue game clicks. Unknown state is NOT empty.
 */
final class StepEngine
{
    enum Action
    {
        INSPECT,
        HARVEST,
        CHECK_HEALTH,
        REMOVE_TREE,
        PAY_REMOVE,
        CHOP_TREE,
        RAKE,
        DIG_STUMP,
        CLEAR_DEAD,
        CURE,
        PLANT,
        COMPOST,
        PROTECT_TREE,
        WATER,
        COMPLETE
    }

    private StepEngine() {}

    static boolean supportsProtection(PatchType type)
    {
        return type == PatchType.TREE || type == PatchType.FRUIT_TREE ||
            type == PatchType.CALQUAT || type == PatchType.HARDWOOD_TREE ||
            type == PatchType.CELASTRUS || type == PatchType.REDWOOD || type == PatchType.CORAL || type == PatchType.SEAWEED ||
            type == PatchType.ALLOTMENT || type == PatchType.HOPS || type == PatchType.BUSH || type == PatchType.CACTUS || type == PatchType.SPIRIT_TREE;
    }

    static boolean isTreeType(PatchType type)
    {
        switch (type)
        {
            case TREE:
            case FRUIT_TREE:
            case CALQUAT:
            case HARDWOOD_TREE:
            case SPIRIT_TREE:
            case CELASTRUS:
            case REDWOOD:
            case CRYSTAL_TREE:
                return true;
            default:
                return false;
        }
    }

    static Action action(PatchType type, @Nullable CropState state,
                         boolean requireProtection, @Nullable Boolean protectedByFarmer)
    {
        if (state == null)
        {
            return Action.INSPECT;
        }
        switch (state)
        {
            case EMPTY:
                return Action.PLANT;
            case DEAD:
                return Action.CLEAR_DEAD;
            case DISEASED:
                return Action.CURE;
            case STUMP:
                return Action.DIG_STUMP;
            case UNCHECKED:
                return isTreeType(type) || type == PatchType.CACTUS || type == PatchType.BUSH ? Action.CHECK_HEALTH : Action.HARVEST;
            case HARVESTABLE:
                if (type == PatchType.SPIRIT_TREE || type == PatchType.REDWOOD) return Action.COMPLETE;
                if (type == PatchType.CELASTRUS || type == PatchType.CRYSTAL_TREE) return Action.HARVEST;
                return isTreeType(type) ? Action.REMOVE_TREE : Action.HARVEST;
            case GROWING:
                if (supportsProtection(type) && requireProtection
                    && !Boolean.TRUE.equals(protectedByFarmer))
                {
                    return Action.PROTECT_TREE;
                }
                return Action.COMPLETE;
            default:
                return Action.INSPECT;
        }
    }

    static boolean keepExisting(PatchType type, CropState state)
    {
        if (state != CropState.UNCHECKED && state != CropState.HARVESTABLE && state != CropState.DISEASED)
            return false;
        return type == PatchType.SPIRIT_TREE || type == PatchType.REDWOOD ||
            type == PatchType.BUSH || type == PatchType.CACTUS;
    }

    static Action refine(Action action, boolean payRemoval, boolean knownGardener, boolean weeds)
    {
        if (action == Action.REMOVE_TREE) return payRemoval && knownGardener ? Action.PAY_REMOVE : Action.CHOP_TREE;
        if (action == Action.PLANT && weeds) return Action.RAKE;
        return action;
    }

    static String instruction(Action action, Crop crop, PatchType type)
    {
        return instruction(action, crop, type, true);
    }

    static String instruction(Action action, Crop crop, PatchType type, boolean compost)
    {
        String name = crop == null ? "a suitable replacement crop" : crop.getName();
        switch (action)
        {
            case HARVEST:
                if (type == PatchType.HESPORI)
                    return "Prepare for Hespori combat if alive; harvest only after defeating it. Replant manually when appropriate.";
                if (type == PatchType.CORAL) return "Collect the mature coral, then replant if the nursery is empty.";
                if (type == PatchType.CRYSTAL_TREE) return "Harvest the crystal shards, then plant a crystal sapling if the patch is empty.";
                if (type == PatchType.CELASTRUS)
                    return crop == null ? "Harvest the bark and leave the tree planted; no replacement allocated."
                        : "Harvest the bark if available, then remove the harvested tree and replant if desired.";
                if (crop == null && (type == PatchType.FRUIT_TREE || type == PatchType.CALQUAT))
                    return "Pick the fruit and leave the tree planted. Use Skip if finished and the patch has not advanced.";
                return crop == null
                    ? "Harvest this patch and leave the existing crop planted if it regrows."
                    : "Harvest this " + type.getDisplayName().toLowerCase() +
                        " patch, then replant " + name + " if appropriate.";
            case CHECK_HEALTH:
                if (type == PatchType.SPIRIT_TREE) return "Check health and leave the spirit tree planted for travel.";
                if (type == PatchType.REDWOOD) return "Check health and leave the redwood planted.";
                if (type == PatchType.CACTUS) return "Check health and pick the cactus produce.";
                if (type == PatchType.BUSH) return "Check health, harvest the berries and leave the bush planted.";
                if (type == PatchType.CELASTRUS) return crop == null
                    ? "Check health, then harvest the bark and leave the tree planted."
                    : "Check health, then harvest the bark before removing the tree.";
