import java.util.*;
import net.runelite.api.gameval.ItemID;

/** Inventory guidance is deliberately separate from the full run shopping list. */
final class StepItems
{
    static Set<Integer> select(StepEngine.Action action,PatchType type,Crop crop,int compost,int axe,Map<Integer,Integer> bag)
    {
        Set<Integer> result=new LinkedHashSet<>();
        switch(action)
        {
            case COMPOST: if(compost>=0)result.add(compost);break;
            case PLANT: if(crop!=null)result.add(crop.getItemId());break;
            case RAKE: result.add(ItemID.RAKE);break;
            case DIG_STUMP: case CLEAR_DEAD: result.add(ItemID.SPADE);break;
            case PAY_REMOVE: result.add(ItemID.COINS);break;
            case CHOP_TREE: if(axe>0)result.add(axe);break;
            case CURE:
                if(CropCare.prunes(type))
                    result.add(bag.getOrDefault(ItemID.FAIRY_ENCHANTED_SECATEURS,0)>0?ItemID.FAIRY_ENCHANTED_SECATEURS:ItemID.SECATEURS);
                else result.add(ItemID.PLANT_CURE);
                break;
            case PROTECT_TREE:
                for(ProtectionPayment cost:ProtectionPaymentCatalog.forCrop(crop))result.add(cost.getItemId());
                break;
            default:break;
        }
        return Set.copyOf(result);
    }
    /** Pick one matching slot, in inventory order, irrespective of render traversal. */
    static boolean firstSlot(int id,int index,int[] inventory)
    {
        if(index<0||index>=inventory.length||inventory[index]!=id)return false;
        for(int i=0;i<index;i++)if(inventory[i]==id)return false;
        return true;
    }
    private StepItems(){}
}

package com.farminghelper;

import java.util.*;

/** Character-local last observed stock, not a saved run. Never reads unopened game storage. */
final class StockSnapshot
{
    static String encode(Map<Integer,Integer> items)
    {
        StringJoiner out=new StringJoiner(",");
        new TreeMap<>(items).forEach((id,n)->{if(id>0 && n>0)out.add(id+":"+n);});
        return out.toString();
    }
    static Map<Integer,Integer> decode(String raw)
    {
        Map<Integer,Integer> result=new HashMap<>();
        if(raw==null || raw.isEmpty())return result;
        for(String pair:raw.split(","))
        {
            String[] fields=pair.split(":",-1);
            if(fields.length!=2)continue;
            try {int id=Integer.parseInt(fields[0]),count=Integer.parseInt(fields[1]);if(id>0 && count>0)result.put(id,count);}
            catch(NumberFormatException ignored) { /* Ignore malformed entry, not the whole snapshot. */ }
        }
        return result;
    }
}

