import java.util.*;
import java.util.function.IntFunction;

/** Raw seeds are a separate observed resource; virtual stock is allocation-only. */
final class TreePreparation
{
    static final int FILLED_POT=5354, WATERING_CAN=5331;
    static Map<Integer,Integer> aliases(Map<Integer,Integer> stock,IntFunction<String> name)
    {
        Map<Integer,Integer> result=new TreeMap<>();
        for(int id:stock.keySet())if(stock.get(id)>0&&CropCatalog.findByItemId(id)==null)
        {
            Crop c=VaultRanking.resolve(id,name.apply(id));
            if(c!=null&&c.getName().endsWith(" sapling")&&c.getItemId()!=id)result.put(id,c.getItemId());
        }
        return result;
    }
    static Map<Integer,Integer> allocationStock(Map<Integer,Integer> stock,Map<Integer,Integer> aliases)
    {
        Map<Integer,Integer> result=new HashMap<>(stock);
        aliases.forEach((raw,sapling)->result.merge(sapling,stock.getOrDefault(raw,0),Integer::sum));
        return result;
    }
    static Map<Integer,Integer> preparation(Map<FarmRunPatch,Crop> allocated,Map<Integer,Integer> stock,Map<Integer,Integer> aliases)
    {
        Map<Integer,Integer> need=new LinkedHashMap<>(), result=new LinkedHashMap<>();
        for(Crop c:allocated.values())if(c.getName().endsWith(" sapling"))need.merge(c.getItemId(),c.getQuantity(),Integer::sum);
        for(Map.Entry<Integer,Integer> e:aliases.entrySet())
        {
            int sapling=e.getValue();
            int missing=Math.max(0,need.getOrDefault(sapling,0)-stock.getOrDefault(sapling,0));
            int n=Math.min(missing,stock.getOrDefault(e.getKey(),0));
            if(n>0){result.put(e.getKey(),n);need.merge(sapling,-n,Integer::sum);}
        }
        return result;
    }
    /** Explain the physical raw stock used by the virtual sapling allocation. */
    static String evidence(Map<Integer,Integer> preparation,Map<Integer,Integer> carried,Map<Integer,Integer> bank,Map<Integer,Integer> vault,IntFunction<String> name,boolean bankObserved,boolean vaultObserved)
    {
        StringJoiner out=new StringJoiner("\n");
        new TreeMap<>(preparation).forEach((id,n)->out.add(name.apply(id)+" ×"+n+" needed; carried "+carried.getOrDefault(id,0)+", bank "+bank.getOrDefault(id,0)+(bankObserved?" (observed)":" (cached/unknown)")+", vault "+vault.getOrDefault(id,0)+(vaultObserved?" (observed)":" (cached/unknown)")+"."));
        return out.toString();
    }
    private TreePreparation(){}
}

package com.farminghelper;

import java.util.*;

/** Pure native-slot layout. Coordinates are visual positions, never widget indices.
 * Each section uses only positions already occupied by the native grid. */
final class VaultGrid
{
    static final class Slot
    {
        final int key,x,y,rank;
        final boolean keep;
        Slot(int key,int x,int y,boolean keep,int rank){this.key=key;this.x=x;this.y=y;this.keep=keep;this.rank=rank;}
    }
    static final class Move
    {
        final int key,x,y;
        Move(int key,int x,int y){this.key=key;this.x=x;this.y=y;}
    }
    static final class Section
    {
        final int start,end;
        final List<Slot> slots;
        Section(int start,int end,List<Slot> slots){this.start=start;this.end=end;this.slots=slots;}
    }
    static final class Layout
    {
        final List<Move> moves;
        final boolean hideHeader;
        final int saved;
        Layout(List<Move> moves,boolean hideHeader,int saved){this.moves=moves;this.hideHeader=hideHeader;this.saved=saved;}
    }
    /** Caller verifies the native grid geometry and associated headers first. */
    static Layout layout(Section section,boolean compactSections,int shift)
    {
        List<Slot> slots=new ArrayList<>(section.slots);
        slots.sort(Comparator.comparingInt((Slot s)->s.y).thenComparingInt(s->s.x));
        List<Slot> selected=new ArrayList<>();
        for(Slot s:slots)if(s.keep)selected.add(s);
        selected.sort(Comparator.comparingInt((Slot s)->s.rank).thenComparingInt(s->s.y).thenComparingInt(s->s.x));
        List<Move> moves=new ArrayList<>();
        for(int i=0;i<selected.size();i++)
        {
            Slot position=slots.get(i);
            moves.add(new Move(selected.get(i).key,position.x,position.y-shift));
        }
        if(!compactSections)return new Layout(moves,false,0);
        if(selected.isEmpty())return new Layout(moves,true,Math.max(0,section.end-section.start));
        int saved=slots.get(slots.size()-1).y-slots.get(selected.size()-1).y;
        return new Layout(moves,false,Math.max(0,saved));
    }
    private VaultGrid(){}
}

package com.farminghelper;

import java.util.*;
import java.util.function.Function;

/** Pure selection of existing vault item ids; raw seed aliases never become
 * plantable saplings or inflate the guide's plant-ready inventory. */
final class VaultRanking
{
    enum View
    {
        HIGHEST("Highest XP"), TOP_THREE("Top 3"), CUSTOM("Custom View"), RUN("Active Run");
        final String label;
        View(String label){this.label=label;}
    }

    static final class Entry
    {
        final int id,quantity;
        final Crop crop;
        Entry(int id,int quantity,Crop crop){this.id=id;this.quantity=quantity;this.crop=crop;}
    }

    /** Resolve only recognized native seed names, never guessed item IDs. */
    static Crop resolve(int id,String itemName)
    {
        Crop direct=CropCatalog.findByItemId(id);
        if(direct!=null)return direct;
        if(itemName==null)return null;
        String name=itemName.trim().toLowerCase(Locale.ROOT);
        for(PatchType type:PatchType.values())for(Crop c:CropCatalog.crops(type))
        {
            if(!c.getName().endsWith(" sapling"))continue;
            String base=c.getName().substring(0,c.getName().length()-8).toLowerCase(Locale.ROOT);
            if(name.equals(base+" seed")||name.equals(base+" tree seed")||
                (base.equals("oak")&&name.equals("acorn"))||(base.equals("crystal")&&name.equals("crystal acorn")))return c;
        }
        return null;
    }

    /** Distinct canonical crops, but all of the chosen crop's stocked native
     * seed/sapling representations remain visible. No stock is mutated. */
    static Set<Integer> select(View view,List<Entry> entries,int level,Set<PatchType> allowed,
        Function<PatchType,String> priorities,Map<PatchType,Set<Crop>> overrides)
    {
        if(view==View.RUN)return Collections.emptySet();
        Map<Crop,Map<Integer,Integer>> stock=new LinkedHashMap<>();
        for(Entry entry:entries)
        {
            if(entry.crop==null||entry.quantity<=0||entry.crop.getLevel()>level||!allowed.contains(entry.crop.getPatchType()))continue;
            // A favourite may duplicate the same native item. Never sum duplicate widgets.
            stock.computeIfAbsent(entry.crop,c->new LinkedHashMap<>()).merge(entry.id,entry.quantity,Math::max);
        }
        Set<Integer> selected=new LinkedHashSet<>();
        for(PatchType type:allowed)
        {
            List<Crop> order=new ArrayList<>();
            if(view==View.CUSTOM)
            {
                for(Crop c:overrides.getOrDefault(type,Collections.emptySet()))if(!order.contains(c))order.add(c);
                for(String n:priorities.apply(type).split(","))
                {
                    Crop c=CropCatalog.findByName(type,n.trim());
                    if(c!=null&&!order.contains(c))order.add(c);
                }
            }
            else order.addAll(CropXp.ranked(type,level));
            int limit=view==View.HIGHEST?1:view==View.TOP_THREE?3:Integer.MAX_VALUE;
            int count=0;
            for(Crop crop:order)
            {
                Map<Integer,Integer> quantities=stock.get(crop);
                if(quantities==null||quantities.values().stream().mapToLong(Integer::longValue).sum()<crop.getQuantity())continue;
                selected.addAll(quantities.keySet());
                if(++count>=limit)break;
            }
        }
        return selected;
    }
    /** Exact guide items plus raw seeds corresponding to allocated saplings. */
    static Set<Integer> selectRun(List<Entry> entries,Set<Integer> required)
    {
        Set<Integer> result=new LinkedHashSet<>();
        for(Entry entry:entries)if(entry.quantity>0&&(required.contains(entry.id)||
            entry.crop!=null&&entry.crop.getName().endsWith(" sapling")&&required.contains(entry.crop.getItemId())))result.add(entry.id);
        return result;
    }
    private VaultRanking(){}
}

