package com.farminghelper;

import org.junit.Test;
import static org.junit.Assert.*;

public class WaypointsTest
{
    @Test
    public void farmingGuildRequires65ForBothPatches()
    {
        assertTrue(Waypoints.accessIssue(null, PatchType.TREE,
            "Farming Guild", 64, false).contains("65"));
        assertNull(Waypoints.accessIssue(null, PatchType.TREE,
            "Farming Guild", 65, false));
        assertNull(Waypoints.accessIssue(null, PatchType.HERB,
            "Farming Guild", 65, false));
    }

    @Test
    public void unverifiedLocationsAreConservative()
    {
        assertNotNull(Waypoints.accessIssue(null, PatchType.HERB,
            "Harmony Island", 99, false));
        assertNull(Waypoints.accessIssue(null, PatchType.HERB,
            "Harmony Island", 99, true));
    }

    @Test
    public void guildWingAccessIsSeparateFromCropLevel()
    {
        assertEquals(45, Waypoints.guildAccessLevel(PatchType.BUSH));
        assertEquals(45, Waypoints.guildAccessLevel(PatchType.CACTUS));
        assertEquals(65, Waypoints.guildAccessLevel(PatchType.ANIMA));
        assertEquals(85, Waypoints.guildAccessLevel(PatchType.SPIRIT_TREE));
        assertEquals(85, Waypoints.guildAccessLevel(PatchType.CELASTRUS));
        assertEquals(85, Waypoints.guildAccessLevel(PatchType.REDWOOD));
    }

    @Test
    public void missingAccountStateIsNotAnUnlock()
    {
        assertEquals(Waypoints.AccessState.UNKNOWN,
            Waypoints.access(null, PatchType.TREE, "Auburnvale", 99).state);
        assertEquals(Waypoints.AccessState.UNKNOWN,
            Waypoints.access(null, PatchType.FRUIT_TREE, "Lletya", 99).state);
        assertNotNull(Waypoints.access(null, PatchType.HERB,
            "Harmony Island", 99).issue(false));
        assertNull(Waypoints.access(null, PatchType.HERB,
            "Harmony Island", 99).issue(true));
    }

    @Test
    public void standardWaypointsHaveCoordinates()
    {
        assertNotNull(Waypoints.point(PatchType.HERB, "Falador"));
        assertNotNull(Waypoints.point(PatchType.TREE, "Auburnvale"));
        assertNull(Waypoints.point(PatchType.TREE, "Catherby"));
    }
}

package com.farminghelper.queststate;

import java.util.*;
import net.runelite.client.plugins.timetracking.Tab;
import org.junit.Test;
import static org.junit.Assert.*;

public class HealthCheckStateTest
{
    @Test public void allDocumentedHealthChecksAreActionable()
    {
        Map<PatchImplementation,int[]> cases=Map.of(
            PatchImplementation.FRUIT_TREE,new int[]{34,61,98,125,162,189,226,253},
            PatchImplementation.TREE,new int[]{12,21,32,45,60},
            PatchImplementation.HARDWOOD_TREE,new int[]{15,38,63,88,114},
            PatchImplementation.BUSH,new int[]{250,251,252,253,254,255},
            PatchImplementation.CALQUAT,new int[]{34},
            PatchImplementation.SPIRIT_TREE,new int[]{44},
            PatchImplementation.REDWOOD,new int[]{37},
            PatchImplementation.CELASTRUS,new int[]{13},
            PatchImplementation.CRYSTAL_TREE,new int[]{14},
            PatchImplementation.CACTUS,new int[]{31,58});
        for(var e:cases.entrySet())for(int raw:e.getValue())
            assertEquals(e.getKey()+" raw "+raw,CropState.UNCHECKED,QuestFarmingStateReader.normalizedState(e.getKey(),raw,e.getKey().forVarbitValue(raw)));
    }
    @Test public void palmGrowingCheckedStumpAndWeedsRemainDistinct()
    {
        for(int raw=200;raw<=205;raw++)assertEquals(CropState.GROWING,state(PatchImplementation.FRUIT_TREE,raw));
        for(int raw=206;raw<=212;raw++)assertEquals(CropState.HARVESTABLE,state(PatchImplementation.FRUIT_TREE,raw));
        assertEquals(CropState.UNCHECKED,state(PatchImplementation.FRUIT_TREE,226));
        assertEquals(CropState.STUMP,state(PatchImplementation.FRUIT_TREE,225));
        assertEquals(CropState.EMPTY,state(PatchImplementation.FRUIT_TREE,0));
        assertEquals(CropState.EMPTY,state(PatchImplementation.FLOWER,0));
    }
    @Test public void cachedMaturePalmIsNotPredictedAsGrowing()
    {
        net.runelite.api.Client client=org.mockito.Mockito.mock(net.runelite.api.Client.class);
        net.runelite.client.config.ConfigManager config=org.mockito.Mockito.mock(net.runelite.client.config.ConfigManager.class);
        FarmingPatch palm=QuestFarmingStateReader.find(new FarmingWorld(),Tab.FRUIT_TREE,"Gnome Stronghold","",PatchImplementation.FRUIT_TREE);
        long now=java.time.Instant.now().getEpochSecond();
        assertEquals(CropState.UNCHECKED,new FarmingHandler(client,config).predictObserved(palm,"test","226:"+now));
    }
    private static CropState state(PatchImplementation t,int raw)
    {return QuestFarmingStateReader.normalizedState(t,raw,t.forVarbitValue(raw));}
    @Test public void neighbouringPatchIdentitiesCannotAlias()
    {
        FarmingWorld w=new FarmingWorld();
        FarmingPatch strongholdFruit=QuestFarmingStateReader.find(w,Tab.FRUIT_TREE,"Gnome Stronghold","",PatchImplementation.FRUIT_TREE);
        FarmingPatch strongholdTree=QuestFarmingStateReader.find(w,Tab.TREE,"Gnome Stronghold","",PatchImplementation.TREE);
        FarmingPatch villageFruit=QuestFarmingStateReader.find(w,Tab.FRUIT_TREE,"Tree Gnome Village","",PatchImplementation.FRUIT_TREE);
        FarmingPatch flower=QuestFarmingStateReader.find(w,PatchImplementation.FLOWER.getTab(),"Kastori","",PatchImplementation.FLOWER);
        FarmingPatch fruit=QuestFarmingStateReader.find(w,Tab.FRUIT_TREE,"Kastori","",PatchImplementation.FRUIT_TREE);
        FarmingPatch calquat=QuestFarmingStateReader.find(w,PatchImplementation.CALQUAT.getTab(),"Kastori","",PatchImplementation.CALQUAT);
        for(FarmingPatch p:List.of(strongholdFruit,strongholdTree,villageFruit,flower,fruit,calquat))assertNotNull(p);
        assertEquals(6,Set.of(strongholdFruit.configKey(),strongholdTree.configKey(),villageFruit.configKey(),flower.configKey(),fruit.configKey(),calquat.configKey()).size());
    }
}

package com.farminghelper.queststate;

import net.runelite.client.plugins.timetracking.Tab;
import org.junit.Test;
import static org.junit.Assert.*;

public class QuestFarmingStateReaderTest
{
    private final FarmingWorld world = new FarmingWorld();

    @Test
    public void questHelperContainsExistingHerbTreeAndAllotmentPatches()
    {
        assertNotNull(QuestFarmingStateReader.find(world, Tab.HERB, "Falador", null));
        assertNotNull(QuestFarmingStateReader.find(world, Tab.TREE, "Farming Guild", null));
        assertNotNull(QuestFarmingStateReader.find(world, Tab.ALLOTMENT, "Catherby", "North"));
        assertNotNull(QuestFarmingStateReader.find(world, Tab.ALLOTMENT, "Catherby", "South"));
    }

    @Test
    public void canonicalAllotmentPatchesAreSeparate()
    {
        java.util.List<String> names = new java.util.ArrayList<>();
        for (FarmingPatch patch : world.getTabs().get(Tab.ALLOTMENT))
        {
            if ("Falador".equals(patch.getRegion().getName()))
            {
                names.add(patch.getName());
            }
        }
        assertEquals(2, names.size());
        assertNotEquals(names.get(0), names.get(1));
    }

    @Test
    public void harmonyAliasMatchesQuestHelperWorld()
    {
        assertNotNull(QuestFarmingStateReader.find(world, Tab.HERB, "Harmony Island", null));
    }

    @Test
    public void neverTreatUnknownTimeTrackingDataAsEmpty()
    {
        assertEquals(0L, QuestFarmingStateReader.timestampMillis(null));
        assertEquals(0L, QuestFarmingStateReader.timestampMillis(""));
        assertEquals(0L, QuestFarmingStateReader.timestampMillis("3:invalid"));
        assertEquals(0L, QuestFarmingStateReader.timestampMillis("3:0"));
        assertEquals(1000000000000L,
            QuestFarmingStateReader.timestampMillis("99:1000000000"));
    }
}

